         <div class="modal-actions">
           <button class="button button-ghost" data-close-dialog type="button">Cancel</button>
           <button class="button button-danger" type="button">Delete image</button>
         </div>
       </div>
     </dialog>

     <script>
       const h = (tag, props = {}, ...children) => {
         const el = document.createElement(tag);
         Object.entries(props).forEach(([key, value]) => {
           if (key === "className") {
             el.className = value;
           } else if (key.startsWith("on") && typeof value === "function") {
             el.addEventListener(key.slice(2).toLowerCase(), value);
           } else if (value !== false && value != null) {
             el.setAttribute(key, value === true ? "" : value);
           }
         });
         children.flat().forEach((child) => {
           el.append(child instanceof Node ? child : document.createTextNode(child));
         });
         return el;
       };

       function Header() {
         return h("div", {},
           h("p", { className: "eyebrow" }, "Image preview"),
           h("h1", {}, "A clean, focused preview for managing your library"),
           h("p", { className: "copy" }, "Review the asset, then decide whether to keep it or remove it from your collection.")
         );
       }

       function Meta() {
         return h("div", { className: "meta" },
           h("div", { className: "meta-row" }, h("span", {}, "File"), h("span", {}, "sunrise-hero.jpg")),
           h("div", { className: "meta-row" }, h("span", {}, "Size"), h("span", {}, "4.8 MB")),
           h("div", { className: "meta-row" }, h("span", {}, "Uploaded"), h("span", {}, "Today, 09:24"))
         );
       }

       function Actions() {
         return h("div", { className: "actions" },
           h("button", { className: "button button-secondary", type: "button" }, "Share"),
           h("button", { className: "button button-danger trigger", type: "button", "aria-haspopup": "dialog", "aria-controls": "confirm-delete-dialog" }, "Delete image")
         );
       }

       function Preview() {
         return h("section", { className: "preview", "aria-label": "Selected image preview" },
           h("img", {
             src: "https://images.unsplash.com/photo-1493246507139-91e8fad9978e?auto=format&fit=crop&w=1200&q=80",
             alt: "Warm sunrise landscape with soft clouds and mountain silhouettes"
           })
         );
       }

       function Details() {
         return h("section", { className: "details" }, Header(), Meta(), Actions());
       }

       function App() {
         return h("div", { className: "shell" },
           h("article", { className: "card" }, Preview(), Details())
         );
       }

       const app = document.getElementById("app");
       app.appendChild(App());

       const dialog = document.getElementById("confirm-delete-dialog");
       const openTrigger = document.querySelector(".trigger");
       const closeButton = dialog.querySelector("[data-close-dialog]");

       openTrigger.addEventListener("click", () => dialog.showModal());
